fn solve(a: i8, b: i8) -> (i8, i8) {
    // Number of different-type days is the minimum of the two counts
    let different = a.min(b);
    // Compute the remaining items after pairing different types
    // Since different = min(a,b), the remainder is max(a,b) - min(a,b) = |a - b|
    let remainder = a.max(b) - different;
    // Each same-type pair consumes 2 items, so number of same-type days is remainder / 2
    let same = remainder / 2;
    (different, same)
}

